components.css:
.ds-stamp {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 0.65rem 1.15rem;
  border: 2px solid var(--walnut, #6e3b28);
  border-radius: 255px 18px 225px 18px / 18px 225px 18px 255px;
  color: var(--walnut-deep, #4e291c);
  background: transparent;
  font-family: var(--hand, "Shantell Sans", "Segoe Print", "Bradley Hand", cursive);
  font-weight: 600;
  font-size: 1.08rem;
  letter-spacing: -0.02em;
  line-height: 1.1;
  text-align: center;
  text-decoration: none;
  transform: rotate(-1deg);
  cursor: pointer;
}
.ds-stamp:hover {
  background: var(--walnut, #6e3b28);
  color: var(--paper, #f6efe4);
}
.ds-stamp:focus-visible {
  outline: 2px solid var(--walnut-deep, #4e291c);
  outline-offset: 3px;
}

.ds-texty {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  color: var(--ink, #241c16);
  background: transparent;
  font-family: var(--hand, "Shantell Sans", "Segoe Print", "Bradley Hand", cursive);
  font-weight: 600;
  font-size: 1.08rem;
  letter-spacing: -0.02em;
  text-decoration: none;
  border-bottom: 1.5px solid var(--walnut, #6e3b28);
}
.ds-texty:hover { color: var(--walnut-deep, #4e291c); }
.ds-texty:focus-visible {
  outline: 2px solid var(--walnut-deep, #4e291c);
  outline-offset: 3px;
}

.ds-lb {
  min-height: 44px;
  min-width: 44px;
  padding: 0.4rem 0.8rem;
  border: 1.5px solid var(--ink, #241c16);
  background: transparent;
  color: var(--ink, #241c16);
  font-family: var(--hand, "Shantell Sans", "Segoe Print", "Bradley Hand", cursive);
  font-weight: 600;
  font-size: 1.125rem;
  letter-spacing: -0.02em;
  cursor: pointer;
}
.ds-lb:hover {
  background: var(--ink, #241c16);
  color: var(--paper, #f6efe4);
}
.ds-lb:focus-visible {
  outline: 2px solid var(--walnut-deep, #4e291c);
  outline-offset: 3px;
}

.ds-float {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 3.5rem;
  height: 3.5rem;
  border-radius: 50%;
  background: var(--walnut, #6e3b28);
  color: var(--paper, #f6efe4);
  text-decoration: none;
  box-shadow: 0.25rem 0.4rem 0.9rem rgba(36, 28, 22, 0.28);
}
.ds-float svg { width: 1.35rem; height: 1.35rem; }
.ds-float:hover { background: var(--walnut-deep, #4e291c); color: var(--paper, #f6efe4); }
.ds-float:focus-visible {
  outline: 2px solid var(--walnut-deep, #4e291c);
  outline-offset: 3px;
}

.ds-filters {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 0.35rem 0.4rem;
}
.ds-chip {
  display: grid;
  justify-items: start;
  min-height: 48px;
  padding: 0.35rem 0.55rem 0.15rem;
  border: 0;
  background: transparent;
  color: var(--graphite, #4a3b32);
  font-family: var(--hand, "Shantell Sans", "Segoe Print", "Bradley Hand", cursive);
  font-weight: 600;
  font-size: 1.08rem;
  letter-spacing: -0.02em;
  cursor: pointer;
}
.ds-chip svg { width: 100%; height: 0.5rem; display: block; }
.ds-chip path {
  fill: none;
  stroke: var(--walnut, #6e3b28);
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-dasharray: 0.62 0.16;
  stroke-dashoffset: 0;
  stroke-opacity: 0.75;
}
.ds-chip[aria-pressed="true"] { color: var(--ink, #241c16); }
.ds-chip[aria-pressed="true"] path { stroke-dasharray: 1; stroke-opacity: 1; }
.ds-chip:focus-visible {
  outline: 2px solid var(--walnut-deep, #4e291c);
  outline-offset: 3px;
}
@media (prefers-reduced-motion: no-preference) {
  .ds-chip[aria-pressed="true"] path {
    stroke-dashoffset: 1;
    animation: ds-draw 0.7s var(--ease, cubic-bezier(0.16, 1, 0.3, 1)) forwards;
  }
}
@keyframes ds-draw { to { stroke-dashoffset: 0; } }

.ds-study {
  position: relative;
  max-width: 22rem;
  padding: 0.65rem 0.65rem 0.95rem;
  background-color: var(--paper, #f6efe4);
  background-image: url("images/sheet.webp");
  background-size: 260px 260px;
  box-shadow: var(--shadow, 0.45rem 0.7rem 1.15rem rgba(36, 28, 22, 0.16));
  color: var(--ink, #241c16);
  transform: rotate(-1.1deg);
}
.ds-tape {
  position: absolute;
  z-index: 1;
  top: -0.55rem;
  left: 50%;
  width: 3.4rem;
  height: 1.15rem;
  transform: translateX(-50%) rotate(-3deg);
  background: rgba(232, 214, 176, 0.78);
  box-shadow: 0 1px 1px rgba(36, 28, 22, 0.12);
}
.ds-picture {
  width: 100%;
  height: 12rem;
  background: #e7dccb;
}
.ds-study-title {
  margin: 0.75rem 0 0;
  font-family: var(--hand, "Shantell Sans", "Segoe Print", "Bradley Hand", cursive);
  font-weight: 600;
  font-size: 1.55rem;
  line-height: 1.05;
  letter-spacing: -0.03em;
}
.ds-medium {
  margin: 0.15rem 0 0;
  color: var(--graphite, #4a3b32);
  font-family: var(--serif, "Source Serif 4", Palatino, "Palatino Linotype", "Book Antiqua", serif);
  font-size: 1rem;
  line-height: 1.6;
}
.ds-price {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  margin: 0.55rem 0 0;
  padding-bottom: 0.15rem;
  border-bottom: 1px solid rgba(36, 28, 22, 0.28);
  font-family: var(--hand, "Shantell Sans", "Segoe Print", "Bradley Hand", cursive);
  font-size: 0.98rem;
  letter-spacing: -0.02em;
}
.ds-price b {
  font-weight: 600;
  color: var(--walnut-deep, #4e291c);
}
.ds-inquire {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  margin-top: 0.45rem;
  color: var(--walnut-deep, #4e291c);
  font-family: var(--hand, "Shantell Sans", "Segoe Print", "Bradley Hand", cursive);
  font-weight: 600;
  font-size: 1.02rem;
  letter-spacing: -0.02em;
  text-decoration: none;
  border-bottom: 1.5px solid var(--walnut, #6e3b28);
}
.ds-inquire:focus-visible {
  outline: 2px solid var(--walnut-deep, #4e291c);
  outline-offset: 3px;
}
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
  .ds-study { transition: transform 280ms var(--ease, cubic-bezier(0.16, 1, 0.3, 1)); }
  .ds-study:hover { transform: rotate(0deg) translateY(-4px); }
}

.ds-index {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.35rem 1rem;
}
.ds-mark {
  font-family: var(--hand, "Shantell Sans", "Segoe Print", "Bradley Hand", cursive);
  font-weight: 600;
  font-size: 1.45rem;
  letter-spacing: -0.03em;
  color: var(--ink, #241c16);
  text-decoration: none;
  padding: 0.35rem 0;
}
.ds-index nav {
  display: flex;
  flex-wrap: wrap;
  gap: 0.1rem;
}
.ds-index nav a {
  display: inline-flex;
  align-items: center;
  min-height: 44px;
  padding: 0.35rem 0.5rem;
  color: var(--ink, #241c16);
  font-family: var(--hand, "Shantell Sans", "Segoe Print", "Bradley Hand", cursive);
  font-weight: 500;
  font-size: 1.05rem;
  letter-spacing: -0.02em;
  text-decoration: none;
}
.ds-index nav a:hover { color: var(--walnut-deep, #4e291c); }
.ds-mark:focus-visible,
.ds-index nav a:focus-visible {
  outline: 2px solid var(--walnut-deep, #4e291c);
  outline-offset: 3px;
}

.ds-blank {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  margin: 0;
  padding-bottom: 0.15rem;
  border-bottom: 1px solid rgba(36, 28, 22, 0.28);
  color: var(--ink, #241c16);
  font-family: var(--hand, "Shantell Sans", "Segoe Print", "Bradley Hand", cursive);
  font-size: 1.02rem;
  letter-spacing: -0.02em;
}
.ds-blank b {
  font-weight: 600;
  color: var(--walnut-deep, #4e291c);
}

.ds-scrim {
  background: rgba(36, 28, 22, 0.72);
  padding: 0.85rem;
}
.ds-dialog {
  width: min(920px, calc(100% - 1.2rem));
  margin: 0 auto;
  padding: 0.85rem;
  border: 0;
  background: var(--paper, #f6efe4);
  color: var(--ink, #241c16);
  box-shadow: var(--shadow, 0.45rem 0.7rem 1.15rem rgba(36, 28, 22, 0.16));
}
.ds-dialog-top { display: flex; justify-content: flex-end; }
.ds-lb {
  min-height: 44px;
  min-width: 44px;
  padding: 0.4rem 0.8rem;
  border: 1.5px solid var(--ink, #241c16);
  background: transparent;
  color: var(--ink, #241c16);
  font-family: var(--hand, "Shantell Sans", "Segoe Print", "Bradley Hand", cursive);
  font-weight: 600;
  font-size: 1.125rem;
  letter-spacing: -0.02em;
  cursor: pointer;
}
.ds-lb:hover { background: var(--ink, #241c16); color: var(--paper, #f6efe4); }
.ds-lb:focus-visible {
  outline: 2px solid var(--walnut-deep, #4e291c);
  outline-offset: 3px;
}
.ds-well {
  margin-top: 0.55rem;
  height: 10rem;
  background: #e7dccb;
}
.ds-lb-title {
  margin: 0.75rem 0 0;
  font-family: var(--hand, "Shantell Sans", "Segoe Print", "Bradley Hand", cursive);
  font-weight: 600;
  font-size: clamp(1.7rem, 4vw, 2.3rem);
  line-height: 1.05;
  letter-spacing: -0.03em;
}
.ds-rule {
  display: block;
  width: min(9rem, 70%);
  height: 0.55rem;
  margin: 0.1rem 0 0.15rem;
}
.ds-rule path {
  fill: none;
  stroke: var(--walnut, #6e3b28);
  stroke-width: 2.2;
  stroke-linecap: round;
  stroke-dasharray: 1;
}
.ds-medium {
  margin: 0;
  color: var(--graphite, #4a3b32);
  font-family: var(--serif, "Source Serif 4", Palatino, "Palatino Linotype", "Book Antiqua", serif);
  font-size: 1rem;
}
